{
  "id": "webhook-urgent-email",
  "name": "Webhook Urgent Email",
  "nodes": [
    {
      "id": "1a2b3c4d-5e6f-7g8h-9i0j-1k2l3m4n5o6p",
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "httpMethod": "POST",
        "path": "urgent-check",
        "responseMode": "responseNode",
        "options": {}
      }
    },
    {
      "id": "2b3c4d5e-6f7g-8h9i-0j1k-2l3m4n5o6p7q",
      "name": "Check Status",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "conditions": {
          "string": [
            {
              "value1": "={{ $json[\"status\"] }}",
              "operation": "equal",
              "value2": "urgent"
            }
          ]
        }
      }
    },
    {
      "id": "3c4d5e6f-7g8h-9i0j-1k2l-3m4n5o6p7q8r",
      "name": "Send Email",
      "type": "n8n-nodes-base.sendEmail",
      "typeVersion": 1,
      "position": [750, 200],
      "parameters": {
        "fromEmail": "noreply@example.com",
        "toEmail": "admin@example.com",
        "subject": "Urgent Alert: Status is Urgent",
        "text": "A webhook request was received with status: urgent\n\nPayload: {{ JSON.stringify($json, null, 2) }}"
      }
    },
    {
      "id": "4d5e6f7g-8h9i-0j1k-2l3m-4n5o6p7q8r9s",
      "name": "Respond OK",
      "type": "n8n-nodes-base.respondToWebhook",
      "typeVersion": 1,
      "position": [750, 400],
      "parameters": {
        "options": {},
        "responseCode": 200,
        "responseData": {
          "success": true,
          "message": "Webhook received"
        }
      }
    }
  ],
  "connections": {
    "Webhook": {
      "main": [[{"node": "Check Status", "type": "main", "index": 0}]]
    },
    "Check Status": {
      "main": [
        [{"node": "Send Email", "type": "main", "index": 0}],
        [{"node": "Respond OK", "type": "main", "index": 0}]
      ]
    },
    "Send Email": {
      "main": [[{"node": "Respond OK", "type": "main", "index": 0}]]
    }
  }
}

