{
  "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
  "name": "Hourly API to Google Sheets",
  "nodes": [
    {
      "id": "c1e2f3a4-b5c6-7890-d1e2-f3a4b5c6d7e8",
      "name": "Hourly Trigger",
      "type": "n8n-nodes-base.cron",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "hour": 0,
              "minute": 0
            }
          ]
        }
      }
    },
    {
      "id": "d2e3f4a5-b6c7-8901-e2f3-a4b5c6d7e8f9",
      "name": "HTTP Request",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4,
      "position": [500, 300],
      "parameters": {
        "method": "GET",
        "url": "https://api.example.com/data",
        "options": {}
      }
    },
    {
      "id": "e3f4a5b6-c7d8-9012-f3a4-b5c6d7e8f9a0",
      "name": "Filter Results",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [750, 300],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "const filtered = items.filter(item => item.json.status === 'active');\nreturn filtered.map(item => ({ json: item.json }));"
      }
    },
    {
      "id": "f4a5b6c7-d8e9-0123-a4b5-c6d7e8f9a0b1",
      "name": "Google Sheets",
      "type": "n8n-nodes-base.googleSheets",
      "typeVersion": 4,
      "position": [1000, 300],
      "parameters": {
        "operation": "append",
        "sheetId": "YOUR_SHEET_ID",
        "range": "A:Z",
        "options": {
          "valueInputMode": "USER_ENTERED"
        }
      }
    }
  ],
  "connections": {
    "Hourly Trigger": {
      "main": [[{ "node": "HTTP Request", "type": "main", "index": 0 }]]
    },
    "HTTP Request": {
      "main": [[{ "node": "Filter Results", "type": "main", "index": 0 }]]
    },
    "Filter Results": {
      "main": [[{ "node": "Google Sheets", "type": "main", "index": 0 }]]
    }
  }
}

{
  "id": "stripe-invoice-paid-workflow",
  "name": "Stripe Invoice Paid - Update Airtable & Send Email",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Stripe Invoice Paid Trigger",
      "type": "n8n-nodes-base.stripeTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "event": "invoice.payment_succeeded",
        "webhookUrl": "={{ $execution.webhookUrl }}"
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Update Airtable Record",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [500, 200],
      "parameters": {
        "operation": "update",
        "baseId": "={{ $credentials.airtable.baseId }}",
        "tableId": "Invoices",
        "recordId": "={{ $json.data.object.metadata.airtable_record_id }}",
        "fields": {
          "Status": "Paid",
          "Paid Date": "={{ new Date().toISOString() }}",
          "Stripe Invoice ID": "={{ $json.data.object.id }}",
          "Amount Paid": "={{ $json.data.object.amount_paid / 100 }}"
        }
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Send Confirmation Email",
      "type": "n8n-nodes-base.sendEmail",
      "typeVersion": 1,
      "position": [500, 400],
      "parameters": {
        "fromEmail": "billing@company.com",
        "toEmail": "={{ $json.data.object.customer_email }}",
        "subject": "Invoice {{ $json.data.object.number }} - Payment Confirmed",
        "text": "Hi,\n\nYour payment for invoice {{ $json.data.object.number }} ({{ $json.data.object.amount_paid / 100 }} {{ $json.data.object.currency.toUpperCase() }}) has been received.\n\nInvoice Details:\n- Invoice ID: {{ $json.data.object.id }}\n- Amount: {{ $json.data.object.amount_paid / 100 }} {{ $json.data.object.currency.toUpperCase() }}\n- Date: {{ new Date($json.data.object.status_transitions.paid_at * 1000).toLocaleDateString() }}\n\nThank you for your business!\n\nBest regards,\nThe Billing Team"
      }
    }
  ],
  "connections": {
    "Stripe Invoice Paid Trigger": {
      "main": [
        [
          {
            "node": "Update Airtable Record",
            "type": "main",
            "index": 0
          },
          {
            "node": "Send Confirmation Email",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

