{
  "id": "airtable-daily-export",
  "name": "Daily Airtable Export",
  "nodes": [
    {
      "id": "cron-midnight",
      "name": "Cron Midnight",
      "type": "n8n-nodes-base.cron",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "hour": 0,
              "minute": 0
            }
          ]
        }
      }
    },
    {
      "id": "airtable-get-all",
      "name": "Airtable Get All Records",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "operation": "getAll",
        "baseId": "YOUR_BASE_ID",
        "tableId": "YOUR_TABLE_ID",
        "options": {}
      }
    },
    {
      "id": "format-csv",
      "name": "Format as CSV",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "functionCode": "const records = items[0].json.records;\nconst rows = records.map(r => r.fields);\nif (rows.length === 0) return [{json: {csv: ''}}];\nconst headers = Object.keys(rows[0]);\nconst csv = [headers.join(',')].concat(rows.map(r => headers.map(h => JSON.stringify(r[h] || '')).join(','))).join('\\n');\nreturn [{json: {csv}}];"
      }
    },
    {
      "id": "send-email",
      "name": "Send Email with Attachment",
      "type": "n8n-nodes-base.emailSend",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "fromEmail": "your-email@example.com",
        "toEmail": "recipient@example.com",
        "subject": "Daily Airtable Export - {{$now.format('YYYY-MM-DD')}}",
        "text": "Please find attached the daily Airtable export.",
        "attachments": [
          {
            "fileName": "airtable-export-{{$now.format('YYYY-MM-DD')}}.csv",
            "fileContent": "={{$json.csv}}",
            "mimeType": "text/csv"
          }
        ],
        "options": {}
      }
    }
  ],
  "connections": {
    "Cron Midnight": {
      "main": [
        [
          {
            "node": "Airtable Get All Records",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Airtable Get All Records": {
      "main": [
        [
          {
            "node": "Format as CSV",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Format as CSV": {
      "main": [
        [
          {
            "node": "Send Email with Attachment",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

