{
  "id": "google-calendar-reminder-1day",
  "name": "Google Calendar 1-Day Reminder",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Google Calendar Trigger",
      "type": "n8n-nodes-base.googleCalendarTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "mode": "everyTime"
            }
          ]
        },
        "calendars": {
          "calendar": "primary"
        },
        "eventTypes": [
          "created"
        ]
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Calculate Reminder Time",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "functionCode": "const event = items[0].json;\nconst startTime = new Date(event.start.dateTime || event.start.date);\nconst reminderTime = new Date(startTime.getTime() - 24 * 60 * 60 * 1000);\nreturn [{\n  json: {\n    ...event,\n    reminderTime: reminderTime.toISOString(),\n    eventTitle: event.summary,\n    eventStart: startTime.toISOString()\n  }\n}];"
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Wait Until Reminder",
      "type": "n8n-nodes-base.wait",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "waitFor": "dateTime",
        "dateTime": "={{ $json.reminderTime }}"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-defg-456789012345",
      "name": "Send Reminder Email",
      "type": "n8n-nodes-base.gmail",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "operation": "send",
        "fromEmail": "me",
        "toEmail": "={{ $json.attendees?.[0]?.email || 'your-email@example.com' }}",
        "subject": "Reminder: {{ $json.eventTitle }} tomorrow",
        "text": "Hi,\n\nThis is a reminder that your event \"{{ $json.eventTitle }}\" starts tomorrow at {{ new Date($json.eventStart).toLocaleString() }}.\n\nEvent details:\n- Title: {{ $json.eventTitle }}\n- Start: {{ new Date($json.eventStart).toLocaleString() }}\n- Description: {{ $json.description || 'No description' }}\n- Location: {{ $json.location || 'No location' }}\n\nBest regards,\nYour Calendar Assistant"
      }
    }
  ],
  "connections": {
    "Google Calendar Trigger": {
      "main": [[{"node": "Calculate Reminder Time", "type": "main", "index": 0}]]
    },
    "Calculate Reminder Time": {
      "main": [[{"node": "Wait Until Reminder", "type": "main", "index": 0}]]
    },
    "Wait Until Reminder": {
      "main": [[{"node": "Send Reminder Email", "type": "main", "index": 0}]]
    }
  }
}

{
  "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
  "name": "API Status Change Monitor",
  "nodes": [
    {
      "id": "11111111-2222-3333-4444-555555555555",
      "name": "Every 15 Minutes",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1.1,
      "position": [250, 300],
      "parameters": {
        "rule": {
          "interval": 15,
          "unit": "minutes"
        }
      }
    },
    {
      "id": "22222222-3333-4444-5555-666666666666",
      "name": "HTTP Request",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.1,
      "position": [500, 300],
      "parameters": {
        "method": "GET",
        "url": "https://api.example.com/status",
        "options": {},
        "jsonParameters": true,
        "responseFormat": "json"
      }
    },
    {
      "id": "33333333-4444-5555-6666-777777777777",
      "name": "Check Status Change",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "functionCode": "const currentStatus = items[0].json;\nconst previousStatus = workflow.staticData.get('previousStatus');\n\nconst hasChanged = !previousStatus || JSON.stringify(currentStatus) !== JSON.stringify(previousStatus);\n\nif (hasChanged) {\n  workflow.staticData.set('previousStatus', currentStatus);\n}\n\nreturn [{\n  json: {\n    ...currentStatus,\n    statusChanged: hasChanged,\n    previousStatus: previousStatus\n  }\n}];"
      }
    },
    {
      "id": "44444444-5555-6666-7777-888888888888",
      "name": "Status Changed?",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "={{ $json.statusChanged }}",
              "operation": "true"
            }
          ]
        }
      }
    },
    {
      "id": "55555555-6666-7777-8888-999999999999",
      "name": "Send Slack Message",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 2.1,
      "position": [1250, 200],
      "parameters": {
        "resource": "message",
        "operation": "post",
        "channel": "#alerts",
        "text": "🔔 *API Status Changed*\n*New Status:* `{{ $json.status }}`\n*Previous Status:* `{{ $json.previousStatus?.status ?? 'unknown' }}`\n*Timestamp:* {{ new Date().toISOString() }}",
        "options": {
          "asUser": true
        }
      }
    }
  ],
  "connections": {
    "Every 15 Minutes": {
      "main": [[{"node": "HTTP Request", "type": "main", "index": 0}]]
    },
    "HTTP Request": {
      "main": [[{"node": "Check Status Change", "type": "main", "index": 0}]]
    },
    "Check Status Change": {
      "main": [[{"node": "Status Changed?", "type": "main", "index": 0}]]
    },
    "Status Changed?": {
      "main": [
        [{"node": "Send Slack Message", "type": "main", "index": 0}],
        []
      ]
    }
  }
}

