{
  "id": "google-calendar-reminder-workflow",
  "name": "Google Calendar Event Reminder",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Google Calendar Trigger",
      "type": "n8n-nodes-base.googleCalendarTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "event": "created",
        "calendarId": "primary",
        "pollTimes": {
          "item": [
            {
              "mode": "everyHour"
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Calculate Reminder Time",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "functionCode": "const event = items[0].json;\nconst startTime = new Date(event.start.dateTime || event.start.date);\nconst reminderTime = new Date(startTime.getTime() - 24 * 60 * 60 * 1000);\nconst now = new Date();\n\nif (reminderTime <= now) {\n  return [{ json: { ...event, skip: true, reason: 'Reminder time already passed' } }];\n}\n\nconst waitMs = reminderTime.getTime() - now.getTime();\nreturn [{ json: { ...event, reminderTime: reminderTime.toISOString(), waitMs } }];"
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Wait Until Reminder",
      "type": "n8n-nodes-base.wait",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "waitFor": "time",
        "timeUnit": "milliseconds",
        "amount": "={{$json.waitMs}}"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-defa-456789012345",
      "name": "Filter Skipped",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [750, 150],
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "={{$json.skip}}",
              "operation": "isTrue"
            }
          ]
        }
      }
    },
    {
      "id": "e5f6a7b8-c9d0-1234-efab-567890123456",
      "name": "Send Reminder Email",
      "type": "n8n-nodes-base.sendEmail",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "fromEmail": "reminders@example.com",
        "toEmail": "user@example.com",
        "subject": "Reminder: {{ $json.summary || 'Calendar Event' }} tomorrow",
        "text": "Hi,\n\nThis is a reminder for your event:\n\n**{{ $json.summary || 'Untitled Event' }}**\n📅 {{ new Date($json.start.dateTime || $json.start.date).toLocaleString() }}\n📍 {{ $json.location || 'No location specified' }}\n\n{{ $json.description || '' }}\n\n— Your Calendar Reminder"
      }
    }
  ],
  "connections": {
    "Google Calendar Trigger": {
      "main": [
        [
          {
            "node": "Calculate Reminder Time",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Calculate Reminder Time": {
      "main": [
        [
          {
            "node": "Wait Until Reminder",
            "type": "main",
            "index": 0
          },
          {
            "node": "Filter Skipped",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Wait Until Reminder": {
      "main": [
        [
          {
            "node": "Send Reminder Email",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Filter Skipped": {
      "main": [
        [],
        []
      ]
    }
  }
}

{
  "id": "workflow-http-slack-monitor",
  "name": "HTTP API Monitor -> Slack Alert",
  "nodes": [
    {
      "id": "cron-1",
      "name": "Every 15 Minutes",
      "type": "n8n-nodes-base.cron",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "mode": "everyX",
              "value": 15,
              "unit": "minutes"
            }
          ]
        }
      }
    },
    {
      "id": "http-1",
      "name": "HTTP Request",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.1,
      "position": [500, 300],
      "parameters": {
        "method": "GET",
        "url": "https://api.example.com/status",
        "options": {},
        "jsonParameters": true
      }
    },
    {
      "id": "function-1",
      "name": "Detect Change",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "functionCode": "const previous = $getWorkflowStaticData('global').lastStatus;\nconst current = $json;\n\nconst changed = previous !== undefined && JSON.stringify(previous) !== JSON.stringify(current);\n\n$getWorkflowStaticData('global').lastStatus = current;\n\nreturn [{ json: { ...current, changed, previous }}];"
      }
    },
    {
      "id": "if-1",
      "name": "If Changed",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "={{ $json.changed }}",
              "operation": "true"
            }
          ]
        }
      }
    },
    {
      "id": "slack-1",
      "name": "Send Slack Message",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 2.1,
      "position": [1250, 200],
      "parameters": {
        "resource": "message",
        "operation": "post",
        "channel": "#alerts",
        "text": "🔄 Statusänderung erkannt!\nNeuer Status: {{ JSON.stringify($json, null, 2) }}\nVorheriger Status: {{ JSON.stringify($json.previous, null, 2) }}",
        "options": {}
      }
    }
  ],
  "connections": {
    "Every 15 Minutes": {
      "main": [[{ "node": "HTTP Request", "type": "main", "index": 0 }]]
    },
    "HTTP Request": {
      "main": [[{ "node": "Detect Change", "type": "main", "index": 0 }]]
    },
    "Detect Change": {
      "main": [[{ "node": "If Changed", "type": "main", "index": 0 }]]
    },
    "If Changed": {
      "main": [
        [{ "node": "Send Slack Message", "type": "main", "index": 0 }],
        []
      ]
    }
  }
}

