{
  "id": "workflow-http-poll-slack-alert",
  "name": "HTTP API Poll & Slack Alert on Status Change",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Cron Trigger",
      "type": "n8n-nodes-base.cron",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "mode": "everyX",
              "value": 15,
              "unit": "minutes"
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "HTTP Request",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4,
      "position": [500, 300],
      "parameters": {
        "url": "https://api.example.com/status",
        "method": "GET",
        "options": {},
        "jsonParameters": true
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Get Previous Status",
      "type": "n8n-nodes-base.set",
      "typeVersion": 3,
      "position": [750, 200],
      "parameters": {
        "keepOnlySet": false,
        "values": {
          "string": [
            {
              "name": "previousStatus",
              "value": "={{ $workflow.staticData.previousStatus || 'unknown' }}"
            }
          ]
        }
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-defa-456789012345",
      "name": "Check Status Change",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2,
      "position": [750, 300],
      "parameters": {
        "conditions": {
          "string": [
            {
              "value1": "={{ $json.status }}",
              "operation": "notEqual",
              "value2": "={{ $workflow.staticData.previousStatus || 'unknown' }}"
            }
          ]
        }
      }
    },
    {
      "id": "e5f6a7b8-c9d0-1234-efab-567890123456",
      "name": "Send Slack Message",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 2,
      "position": [1000, 300],
      "parameters": {
        "resource": "message",
        "operation": "post",
        "channel": "#alerts",
        "text": "Status changed from *{{ $workflow.staticData.previousStatus || 'unknown' }}* to *{{ $json.status }}*",
        "attachments": []
      }
    },
    {
      "id": "f6a7b8c9-d0e1-2345-fabc-678901234567",
      "name": "Update Stored Status",
      "type": "n8n-nodes-base.set",
      "typeVersion": 3,
      "position": [1000, 400],
      "parameters": {
        "keepOnlySet": true,
        "values": {
          "string": [
            {
              "name": "status",
              "value": "={{ $json.status }}"
            }
          ]
        }
      }
    }
  ],
  "connections": {
    "Cron Trigger": {
      "main": [
        [
          {
            "node": "HTTP Request",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "HTTP Request": {
      "main": [
        [
          {
            "node": "Check Status Change",
            "type": "main",
            "index": 0
          },
          {
            "node": "Get Previous Status",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Get Previous Status": {
      "main": [
        [
          {
            "node": "Check Status Change",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Check Status Change": {
      "main": [
        [
          {
            "node": "Send Slack Message",
            "type": "main",
            "index": 0
          }
        ],
        [
          {
            "node": "Update Stored Status",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Send Slack Message": {
      "main": [
        [
          {
            "node": "Update Stored Status",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

