{
  "id": "google-calendar-reminder-workflow",
  "name": "Google Calendar Event Reminder",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Google Calendar Trigger",
      "type": "n8n-nodes-base.googleCalendarTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerEvents": ["eventCreated"],
        "calendarId": "primary",
        "pollTimes": {
          "item": [
            {
              "mode": "everyMinute"
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Calculate Reminder Time",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "functionCode": "const event = items[0].json;\nconst startTime = new Date(event.start?.dateTime || event.start?.date);\nconst reminderTime = new Date(startTime.getTime() - 24 * 60 * 60 * 1000);\nconst now = new Date();\n\nif (reminderTime <= now) {\n  return [{ json: { ...event, reminderTime: now.toISOString(), sendImmediately: true } }];\n}\n\nreturn [{ json: { ...event, reminderTime: reminderTime.toISOString(), sendImmediately: false } }];"
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
