{
  "id": "workflow-http-poll-slack-alert",
  "name": "HTTP API Poll → Slack on Status Change",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Every 15 Minutes",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "rule": {
          "interval": [15],
          "unit": "minutes"
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Fetch API Status",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4,
      "position": [500, 300],
      "parameters": {
        "url": "https://api.example.com/status",
        "method": "GET",
        "options": {
          "timeout": 10000
        }
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Compare With Previous",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "functionCode": "const current = items[0].json;\nconst previous = $getWorkflowStaticData('global').lastStatus || null;\n\nconst changed = previous !== null && JSON.stringify(current) !== JSON.stringify(previous);\n\n$getWorkflowStaticData('global').lastStatus = current;\n\nreturn [{ json: { ...current, changed, previous } }];"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-def4-567890123456",
      "name": "Status Changed?",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "={{ $json.changed }}",
              "operation": "true"
            }
          ]
        }
      }
    },
    {
      "id": "e5f6a7b8-c9d0-1234-ef56-789012345678",
      "name": "Send Slack Alert",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 1,
      "position": [1250, 200],
      "parameters": {
        "resource": "message",
        "operation": "post",
        "channel": "#alerts",
        "text": "⚠️ *Status Change Detected*\n*Previous:* `{{ $json.previous }}`\n*Current:* `{{ $json }}`",
        "options": {
          "username": "API Monitor",
          "iconEmoji": ":warning:"
        }
      }
    }
  ],
  "connections": {
    "Every 15 Minutes": {
      "main": [[{ "node": "Fetch API Status", "type": "main", "index": 0 }]]
    },
    "Fetch API Status": {
      "main": [[{ "node": "Compare With Previous", "type": "main", "index": 0 }]]
    },
    "Compare With Previous": {
      "main": [[{ "node": "Status Changed?", "type": "main", "index": 0 }]]
    },
    "Status Changed?": {
      "main": [
        [{ "node": "Send Slack Alert", "type": "main", "index": 0 }],
        []
      ]
    }
  }
}

